// Canvas Confetti - Ultra Lightweight & Zero CPU Overhead for Intel Atom
(function(window) {
  'use strict';
  function ConfettiEngine() {
    var canvas = null;
    var ctx = null;
    var particles = [];
    var animationId = null;
    var colors = ['#00f0ff', '#ffd700', '#10b981', '#f43f5e', '#a855f7', '#fb923c'];

    function initCanvas() {
      if (!canvas) {
        canvas = document.createElement('canvas');
        canvas.id = 'confetti-canvas-global';
        canvas.style.position = 'fixed';
        canvas.style.top = '0';
        canvas.style.left = '0';
        canvas.style.width = '100vw';
        canvas.style.height = '100vh';
        canvas.style.zIndex = '99999';
        canvas.style.pointerEvents = 'none';
        document.body.appendChild(canvas);
        ctx = canvas.getContext('2d');
        resize();
        window.addEventListener('resize', resize, false);
      }
    }

    function resize() {
      if (canvas) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }
    }

    function createParticle(x, y) {
      return {
        x: x || canvas.width * (0.2 + Math.random() * 0.6),
        y: y || canvas.height * 0.4,
        vx: (Math.random() - 0.5) * 12,
        vy: -Math.random() * 10 - 4,
        size: Math.random() * 8 + 4,
        color: colors[Math.floor(Math.random() * colors.length)],
        rotation: Math.random() * 360,
        vrot: (Math.random() - 0.5) * 10,
        alpha: 1,
        decay: Math.random() * 0.015 + 0.01
      };
    }

    function step() {
      if (!ctx || particles.length === 0) {
        if (animationId) cancelAnimationFrame(animationId);
        animationId = null;
        if (canvas) ctx.clearRect(0, 0, canvas.width, canvas.height);
        return;
      }

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (var i = particles.length - 1; i >= 0; i--) {
        var p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.28; // gravidade
        p.rotation += p.vrot;
        p.alpha -= p.decay;

        if (p.alpha <= 0 || p.y > canvas.height + 20) {
          particles.splice(i, 1);
          continue;
        }

        ctx.save();
        ctx.globalAlpha = Math.max(0, p.alpha);
        ctx.translate(p.x, p.y);
        ctx.rotate((p.rotation * Math.PI) / 180);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.6);
        ctx.restore();
      }

      animationId = requestAnimationFrame(step);
    }

    return function fire(opts) {
      initCanvas();
      opts = opts || {};
      var count = opts.particleCount || 45;
      for (var i = 0; i < count; i++) {
        particles.push(createParticle(opts.x, opts.y));
      }
      if (!animationId) {
        animationId = requestAnimationFrame(step);
      }
    };
  }

  var confetti = ConfettiEngine();
  window.confetti = confetti;
})(window);
